import{_ as e,o as d,c as o,ae as r}from"./chunks/framework.BX6FPmO9.js";const p=JSON.parse('{"title":"文件命名與權重","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/doc-naming.md","filePath":"conventions/doc-naming.md"}'),a={name:"conventions/doc-naming.md"};function n(s,t,c,i,h,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="文件命名與權重" tabindex="-1">文件命名與權重 <a class="header-anchor" href="#文件命名與權重" aria-label="Permalink to &quot;文件命名與權重&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件定義 <strong>docs/</strong> 與 <strong>specs/</strong> 內 Markdown 的類型與權重，讓開發者與 AI 一眼辨識「必讀／必遵 vs 參考／按需」。</p><hr><h2 id="類型-type" tabindex="-1">類型（type） <a class="header-anchor" href="#類型-type" aria-label="Permalink to &quot;類型（type）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>類型</th><th>說明</th><th>典型位置</th></tr></thead><tbody><tr><td><strong>entry</strong></td><td>入口、總覽；先看這份再決定往哪查</td><td>根目錄 README、AGENTS、docs/README；docs 根目錄 UPPERCASE stub</td></tr><tr><td><strong>spec</strong></td><td>規格／契約／必遵；審查與實作須符合</td><td>code-review-spec、specs/api/*、conventions 內制度類</td></tr><tr><td><strong>reference</strong></td><td>參考；依需要查閱</td><td>architecture/<em>、product/</em>、conventions 內說明類</td></tr><tr><td><strong>runbook</strong></td><td>操作程序；依情境執行</td><td>runbooks/*</td></tr><tr><td><strong>adr</strong></td><td>架構決策或討論摘要</td><td>adr/*</td></tr><tr><td><strong>report</strong></td><td>產出報告、盤查結果；非長期規格</td><td>audit-report 等</td></tr></tbody></table><hr><h2 id="權重-weight" tabindex="-1">權重（weight） <a class="header-anchor" href="#權重-weight" aria-label="Permalink to &quot;權重（weight）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>權重</th><th>說明</th><th>何時看</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>必讀／必遵</td><td>入職、PR 前、審查時必須對齊</td></tr><tr><td><strong>2</strong></td><td>常用</td><td>開發與重構時經常參照</td></tr><tr><td><strong>3</strong></td><td>按需</td><td>遇到該主題時再查</td></tr></tbody></table><hr><h2 id="檔名與目錄約定" tabindex="-1">檔名與目錄約定 <a class="header-anchor" href="#檔名與目錄約定" aria-label="Permalink to &quot;檔名與目錄約定&quot;">​</a></h2><ul><li><strong>根目錄</strong>：<code>README.md</code>、<code>AGENTS.md</code>、<code>AGENT_CAPABILITIES.md</code>、<code>CONTRIBUTING.md</code> 等大寫或 Pascal，表示入口或高權重。</li><li><strong>docs/ 根目錄</strong>：<code>ARCHITECTURE.md</code>、<code>CONVENTIONS.md</code>、<code>DEVELOPMENT.md</code> 等 UPPERCASE 為入口 stub；其餘用 kebab-case（如 <code>code-review-spec.md</code>、<code>audit-report.md</code>）。</li><li><strong>docs 子目錄</strong>：一律 <strong>kebab-case</strong>（如 <code>system-overview.md</code>、<code>data-test-driven.md</code>）。</li><li><strong>specs/</strong>：kebab-case（如 <code>handler-mapping.md</code>、<code>contract-schema.md</code>）。</li></ul><p>未來若以「檔名前綴」標示類型，可選：<code>spec-*</code>、<code>runbook-*</code>、<code>adr-*</code>、<code>report-*</code>；既有檔案可漸進更名並更新連結。</p><hr><h2 id="每份文件開頭標示" tabindex="-1">每份文件開頭標示 <a class="header-anchor" href="#每份文件開頭標示" aria-label="Permalink to &quot;每份文件開頭標示&quot;">​</a></h2><p>為讓一打開檔案就知權重，建議在標題下加一行：</p><ul><li><strong>類型</strong>：entry | spec | reference | runbook | adr | report</li><li><strong>權重</strong>：1 | 2 | 3</li></ul><p>例：<code>**類型**：spec | **權重**：1</code></p><p>或於文件第一段首句寫明「本文件為<strong>必遵規範</strong>」／「本文件為<strong>參考</strong>」。</p><hr><h2 id="一覽表" tabindex="-1">一覽表 <a class="header-anchor" href="#一覽表" aria-label="Permalink to &quot;一覽表&quot;">​</a></h2><p>完整一覽與各檔類型／權重見 <a href="./../README.html">docs/README.md</a>。</p>',22)])])}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
